import re, os

WS = "routers/cowork_agent"

def patch(path, replacements):
    with open(path) as f:
        src = f.read()
    orig = src
    for old, new in replacements:
        if old not in src:
            print(f"WARN: pattern not found in {path}: {old[:70]!r}")
            continue
        src = src.replace(old, new, 1)
    if src != orig:
        with open(path, "w") as f:
            f.write(src)
        print(f"OK: {path}")
    else:
        print(f"SKIP: {path}")

